ente</option><option value="none" @selected(old('prorata',$version->prorata ?? '')==='none')>Nessun prorata: quota intera</option><option value="daily" @selected(old('prorata',$version->prorata ?? '')==='daily')>Giorni effettivi di iscrizione</option></select></label><label class="flex min-h-12 items-center gap-3 text-sm"><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$version->is_active ?? true)) class="size-5 accent-teal-800">Piano attivo da questa versione</label></div>
